    --sidemenu_lvl3_bgcolor:transparent;
    --sidemenu_lvl4_bgcolor:transparent;
    --sidemenu_lvl5_bgcolor:transparent;
    --sidemenu_lvl6_bgcolor:transparent;
    --sidemenu_lvl7_bgcolor:transparent; /* lightest */
    /* EVENTS */
