@media (max-width: 960px) {
    body #evo_main_menu {margin:0 auto !important;}
    /* main menu */
    div#evo_main_menu_wrapper {
        left: -104%;
        transition: left 0.5s ease !important;
        position: fixed;
        top: 130px;
        width: 102vw;
        height: 100vh;
        overflow-y: auto;
        margin-top: 0px;
