/* Slide Button */
a.btn-slide {
    display: inline-block;
    padding: .5rem 1rem;
    font-size: var(--btn-font-size);
    font-weight: 700;
    color: var(--button-text-color-before);
    border: var(--btn-border-thickness) solid var(--btn-border-color);
    border-radius:10px;
    cursor: pointer;
    position: relative;
    background-color: var(--btn-bg);
    text-decoration: none;
    overflow: hidden;
    z-index: 1;
    font-family: inherit;
    width:max-content;
    max-width:200px;
    text-transform: uppercase;
}
a.btn-slide::before {
     position: absolute;
     content: "";
     left: 0;
     top: 0;
     width: 100%;
     height: 100%;
     background-color: var(--btn-bg-hover);
     transform: translateX(-100%);
     transition: all .3s;
     z-index: -1;
     color:#fff !important;
}
a.btn-slide:hover::before {
    transform: translateX(0);
    color: #fff !important;
}
a.btn-slide:hover {color:var(--button-text-color-hover);}

/* Glow Button */
a.btn-glow {
    position: relative;
    padding: .5rem 1rem;;
    border-radius: 10px;
    border: var(--btn-border-thickness) solid var(--btn-border-color);
    font-size: var(--btn-font-size);
    background: var(--btn-bg);
    color: var(--button-text-color-before);
    width:max-content;
    max-width:200px;
    text-transform: uppercase;
    font-weight: 600;
    text-decoration:none;

    overflow: hidden;
    box-shadow: 0 0 0 0 transparent;
    -webkit-transition: all 0.2s ease-in;
    -moz-transition: all 0.2s ease-in;
    transition: all 0.2s ease-in;
}
a.btn-glow:hover {
  background: var(--btn-bg-hover);
  box-shadow: 0 0 30px 5px rgba(0, 142, 236, 0.815);
  -webkit-transition: all 0.2s ease-out;
  -moz-transition: all 0.2s ease-out;
  transition: all 0.2s ease-out;
  color:var(--button-text-color-hover);
}
a.btn-glow:hover::before {
  -webkit-animation: sh02 0.5s 0s linear;
  -moz-animation: sh02 0.5s 0s linear;
  animation: sh02 0.5s 0s linear;
}
a.btn-glow::before {
  content: '';
  display: block;
  width: 0px;
  height: 86%;
  position: absolute;
  top: 7%;
  left: 0%;
  opacity: 0;
  background: #fff;
  box-shadow: 0 0 50px 30px #fff;
  -webkit-transform: skewX(-20deg);
  -moz-transform: skewX(-20deg);
  -ms-transform: skewX(-20deg);
  -o-transform: skewX(-20deg);
  transform: skewX(-20deg);
}
@keyframes sh02 {
  from {opacity: 0;left: 0%;}
  50% {opacity: 1;}
  to {opacity: 0;left: 100%;}
}
a.btn-glow:active {
  box-shadow: 0 0 0 0 transparent;
  -webkit-transition: box-shadow 0.2s ease-in;
  -moz-transition: box-shadow 0.2s ease-in;
  transition: box-shadow 0.2s ease-in;
}

/* Pulse Button */
button.btn-pulse {
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: 10px;
    box-shadow: 0px 6px 24px 0px rgba(0, 0, 0, 0.2);
    overflow: hidden;
    cursor: pointer;
    position: relative;
    padding: 1rem 1.5rem;;
    border: none;
    font-size: var(--btn-font-size);
    background: #183153;
    color: #fff;
    width:max-content;
    max-width:200px;
    text-transform: uppercase;
    font-weight: 600;
    text-decoration:none;

}
button.btn-pulse:after {
    content: " ";
    width: 0%;
    height: 100%;
    background: #ffd401;
    position: absolute;
    transition: all 0.4s ease-in-out;
    right: 0;
}
button.btn-pulse:hover::after {
  right: auto;
  left: 0;
  width: 100%;
}
button.btn-pulse span {
  text-align: center;
  text-decoration: none;
  width: 100%;
  color: ;
  font-size: 1.1rem;
  font-weight: 700;
  z-index: 20;
  transition: all 0.3s ease-in-out;
}
button.btn-pulse:hover span {
  color: #183153;
  animation: scaleUp 0.3s ease-in-out;
}
@keyframes scaleUp {
  0% {transform: scale(1);}
  50% {transform: scale(0.95);}
  100% {transform: scale(1);}
}

/* Push Button */
a.btn-push {
    color: #ecf0f1;
    font-size: 1.1rem;
    background-color: #e67e22;
    border: 1px solid #f39c12;
    border-radius: 10px;
